from fractions import Fraction as F
from itertools import combinations

def fits_line(pairs):
    """Is there one rule y = k*x + c through all these (x, y)?"""
    (x1, y1), (x2, y2) = pairs[0], pairs[1]
    if x1 == x2:
        return False
    k = F(y2 - y1, x2 - x1)
    c = y1 - k * x1
    return all(y == k * x + c for x, y in pairs)

RULES = {
    "square": lambda x, y: y == x * x,
    "n(n+1)": lambda x, y: y == x * (x + 1),
    "cube": lambda x, y: y == x ** 3,
}

def odd_pair(options):
    odd = set()
    keys = list(options)
    for trio in combinations(keys, 3):
        if fits_line([options[k] for k in trio]) and not fits_line([options[k] for k in keys]):
            odd |= set(keys) - set(trio)
    for rule in RULES.values():
        ok = [k for k in keys if rule(*options[k])]
        if len(ok) == 3:
            odd |= set(keys) - set(ok)
    assert len(odd) == 1, odd
    return odd.pop()

# Worked example 2024-09-09_1230_R18: y = 3x + 3
assert odd_pair({"A": (15, 48), "B": (12, 39), "C": (13, 42), "D": (11, 35)}) == "D"
# 2024-09-09_0900_R04: constant difference 216
assert odd_pair({"A": (335, 119), "B": (358, 152), "C": (317, 101), "D": (308, 92)}) == "B"
# 2024-09-09_1600_R04: constant ratio 7/3
assert odd_pair({"A": (36, 84), "B": (33, 72), "C": (66, 154), "D": (72, 168)}) == "B"
# Constructed: squares
assert odd_pair({"A": (7, 49), "B": (9, 81), "C": (12, 144), "D": (13, 196)}) == "D"

from fractions import Fraction as F
from itertools import combinations

OPS = {"a+b": lambda a, b: a + b, "a*b": lambda a, b: a * b, "a-b": lambda a, b: a - b}

def rule_fits(op, triads):
    """Is there one rule c = p*op(a, b) + q (p, q fixed) through all these triads?"""
    pts = [(op(a, b), c) for a, b, c in triads]
    xs = {x for x, _ in pts}
    if len(xs) < 2:
        return False
    (x1, y1), (x2, y2) = sorted(set(pts))[:2]
    if x1 == x2:
        return False
    p = F(y2 - y1, x2 - x1)
    q = y1 - p * x1
    return p != 0 and all(y == p * x + q for x, y in pts) and p.denominator == 1 and q.denominator == 1

def odd_triad(options):
    keys = list(options)
    odd = set()
    for name, op in OPS.items():
        if rule_fits(op, [options[k] for k in keys]):
            continue
        for trio in combinations(keys, 3):
            if rule_fits(op, [options[k] for k in trio]):
                odd |= set(keys) - set(trio)
    assert len(odd) == 1, odd
    return odd.pop()

# Worked example 2024-09-12_1230_R12: c = (a+b)*11
assert odd_triad({"A": (12, 7, 209), "B": (19, 11, 330), "C": (23, 8, 343), "D": (15, 9, 264)}) == "C"
# 2024-09-10_0900_R10: c = a*b
assert odd_triad({"A": (2, 2, 4), "B": (1, 3, 3), "C": (2, 4, 8), "D": (3, 2, 5)}) == "D"
# 2024-09-13_0900_R16: c = a*b + 5
assert odd_triad({"A": (31, 5, 160), "B": (13, 8, 109), "C": (21, 4, 89), "D": (27, 9, 243)}) == "D"
# Constructed: c = 2(a+b)
assert odd_triad({"A": (3, 4, 14), "B": (5, 6, 22), "C": (7, 2, 18), "D": (8, 1, 20)}) == "D"

from math import isqrt

def is_prime(n):
    return n > 1 and all(n % d for d in range(2, isqrt(n) + 1))

def icbrt(n):
    r = round(n ** (1 / 3))
    return next((x for x in (r - 1, r, r + 1) if x ** 3 == n), None)

PROPS = {"prime": is_prime, "square": lambda n: isqrt(n) ** 2 == n, "cube": lambda n: icbrt(n) is not None,
         "even": lambda n: n % 2 == 0}
for k in range(3, 14):
    PROPS[f"div{k}"] = lambda n, k=k: n % k == 0

def odd_number(options):
    odd = set()
    for test in PROPS.values():
        has = [k for k, n in options.items() if test(n)]
        if len(has) == 3:
            odd |= set(options) - set(has)
    assert len(odd) == 1, odd
    return odd.pop()

# Worked example 2024-09-24_1600_R24: 829, 643, 821 prime; 237 = 3 x 79
assert 237 == 3 * 79 and all(is_prime(n) for n in (829, 643, 821))
assert odd_number({"A": 829, "B": 237, "C": 643, "D": 821}) == "B"
# Constructed: perfect squares
assert odd_number({"A": 121, "B": 169, "C": 250, "D": 225}) == "C"
# Constructed: perfect cubes
assert odd_number({"A": 343, "B": 512, "C": 729, "D": 900}) == "D"
